class Solution {
public:
    vector<int> splitIntoFibonacci(string num) {
        int n = num.size();
        for (int i = 1; i <= 10 && i < n; i++) {
            if (num[0] == '0' && i > 1) break;
            long long a = 0;
            bool okA = true;
            for (int k = 0; k < i; k++) {
                a = a * 10 + (num[k] - '0');
                if (a >= (1LL << 31)) { okA = false; break; }
            }
            if (!okA) break;
            for (int j = 1; j <= 10 && i + j < n; j++) {
                if (num[i] == '0' && j > 1) break;
                long long b = 0;
                bool okB = true;
                for (int k = i; k < i + j; k++) {
                    b = b * 10 + (num[k] - '0');
                    if (b >= (1LL << 31)) { okB = false; break; }
                }
                if (!okB) break;
                vector<int> res = {(int)a, (int)b};
                int idx = i + j;
                long long x = a, y = b;
                bool valid = true;
                while (idx < n) {
                    long long z = x + y;
                    if (z >= (1LL << 31)) { valid = false; break; }
                    string zs = to_string(z);
                    if (num.compare(idx, zs.size(), zs) != 0) { valid = false; break; }
                    idx += zs.size();
                    res.push_back((int)z);
                    x = y; y = z;
                }
                if (valid && (int)res.size() >= 3 && idx == n) return res;
            }
        }
        return {};
    }
};
